  "inlineSchema": "// ============================================================\n// Hurumu Woreda Administration Portal — Prisma Schema\n// Database: PostgreSQL\n// ============================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\")\n  directUrl = env(\"DIRECT_URL\")\n}\n\n// ─── Enums ────────────────────────────────────────────────────────\n\nenum Role {\n  SUPER_ADMIN\n  ADMIN\n  DEPARTMENT_HEAD\n  STAFF\n  PUBLIC\n}\n\nenum NewsStatus {\n  DRAFT\n  PUBLISHED\n  ARCHIVED\n}\n\nenum NewsTag {\n  ANNOUNCEMENT\n  EVENT\n  NOTICE\n  PROJECT\n  TENDER\n}\n\nenum ServiceCategory {\n  CIVIL_REGISTRATION\n  LAND_ADMINISTRATION\n  BUSINESS_LICENSE\n  AGRICULTURE\n  HEALTH\n  EDUCATION\n  INFRASTRUCTURE\n  SOCIAL_SERVICES\n  FINANCE\n  OTHER\n}\n\nenum DocumentType {\n  BUDGET_REPORT\n  PROCUREMENT_PLAN\n  PERFORMANCE_REPORT\n  POLICY\n  GUIDELINE\n  TENDER_DOCUMENT\n  ANNUAL_PLAN\n  OTHER\n}\n\nenum ApplicationStatus {\n  PENDING\n  UNDER_REVIEW\n  APPROVED\n  REJECTED\n  REQUIRES_DOCUMENTS\n}\n\n// ─── Core: Users & Auth ──────────────────────────────────────────\n\nmodel User {\n  id           String  @id @default(cuid())\n  email        String  @unique\n  fullName     String\n  phone        String?\n  passwordHash String\n  role         Role    @default(STAFF)\n  isActive     Boolean @default(true)\n  avatarUrl    String?\n\n  departmentId String?\n  department   Department? @relation(fields: [departmentId], references: [id])\n\n  refreshTokens RefreshToken[]\n  newsItems     News[]         @relation(\"NewsAuthor\")\n  documents     Document[]     @relation(\"DocumentUploader\")\n  auditLogs     AuditLog[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([email])\n  @@index([role])\n}\n\nmodel RefreshToken {\n  id        String   @id @default(cuid())\n  token     String   @unique\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  expiresAt DateTime\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n}\n\n// ─── Organizational: Departments & Kebeles ───────────────────────\n\nmodel Department {\n  id          String  @id @default(cuid())\n  name        String  @unique\n  nameOromoo  String?\n  nameAmharic String?\n  slug        String  @unique\n  description String?\n  iconName    String?\n  headName    String?\n  phone       String?\n  email       String?\n  isActive    Boolean @default(true)\n  sortOrder   Int     @default(0)\n\n  users     User[]\n  services  Service[]\n  news      News[]\n  documents Document[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([slug])\n}\n\nmodel Kebele {\n  id          String  @id @default(cuid())\n  name        String  @unique\n  nameOromoo  String?\n  number      Int     @unique\n  population  Int?\n  area        Float? // km²\n  chairperson String?\n  phone       String?\n\n  serviceApplications ServiceApplication[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ─── Content: News & Announcements ──────────────────────────────\n\nmodel News {\n  id            String     @id @default(cuid())\n  title         String\n  titleOromoo   String?\n  titleAmharic  String?\n  slug          String     @unique\n  excerpt       String\n  content       String // Rich text / markdown\n  tag           NewsTag    @default(ANNOUNCEMENT)\n  status        NewsStatus @default(DRAFT)\n  isUrgent      Boolean    @default(false)\n  featuredImage String?\n  publishedAt   DateTime?\n  viewCount     Int        @default(0)\n\n  authorId String\n  author   User   @relation(\"NewsAuthor\", fields: [authorId], references: [id])\n\n  departmentId String?\n  department   Department? @relation(fields: [departmentId], references: [id])\n\n  tags NewsTagRelation[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status, publishedAt])\n  @@index([slug])\n  @@index([tag])\n}\n\nmodel NewsTagRelation {\n  newsId   String\n  tagLabel String\n  news     News   @relation(fields: [newsId], references: [id], onDelete: Cascade)\n\n  @@id([newsId, tagLabel])\n}\n\n// ─── Services & Applications ─────────────────────────────────────\n\nmodel Service {\n  id             String          @id @default(cuid())\n  name           String\n  nameOromoo     String?\n  nameAmharic    String?\n  slug           String          @unique\n  description    String\n  category       ServiceCategory\n  iconName       String?\n  fee            Float? // in ETB\n  processingDays Int?\n  requiredDocs   String[] // list of required documents\n  steps          String[] // process steps\n  isOnline       Boolean         @default(false)\n  isActive       Boolean         @default(true)\n  sortOrder      Int             @default(0)\n\n  departmentId String?\n  department   Department? @relation(fields: [departmentId], references: [id])\n\n  applications ServiceApplication[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([category])\n  @@index([slug])\n}\n\nmodel ServiceApplication {\n  id              String            @id @default(cuid())\n  referenceNumber String            @unique @default(cuid())\n  applicantName   String\n  applicantPhone  String\n  applicantEmail  String?\n  description     String?\n  status          ApplicationStatus @default(PENDING)\n  reviewNotes     String?\n  attachments     String[] // file URLs\n\n  serviceId String\n  service   Service @relation(fields: [serviceId], references: [id])\n\n  kebeleId String?\n  kebele   Kebele? @relation(fields: [kebeleId], references: [id])\n\n  submittedAt DateTime  @default(now())\n  reviewedAt  DateTime?\n  resolvedAt  DateTime?\n  updatedAt   DateTime  @updatedAt\n\n  @@index([status])\n  @@index([referenceNumber])\n  @@index([serviceId])\n}\n\n// ─── Documents & Transparency ────────────────────────────────────\n\nmodel Document {\n  id            String       @id @default(cuid())\n  title         String\n  titleOromoo   String?\n  description   String?\n  type          DocumentType\n  fileUrl       String\n  fileSize      Int? // bytes\n  mimeType      String?\n  fiscalYear    String? // e.g. \"2025/26\"\n  quarter       Int? // 1–4\n  isPublic      Boolean      @default(true)\n  downloadCount Int          @default(0)\n\n  uploadedById String\n  uploadedBy   User   @relation(\"DocumentUploader\", fields: [uploadedById], references: [id])\n\n  departmentId String?\n  department   Department? @relation(fields: [departmentId], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([type])\n  @@index([isPublic])\n  @@index([fiscalYear])\n}\n\n// ─── Site Config (key-value for dynamic settings) ────────────────\n\nmodel SiteConfig {\n  key       String   @id\n  value     String\n  label     String?\n  updatedAt DateTime @updatedAt\n}\n\n// ─── Audit Log ───────────────────────────────────────────────────\n\nmodel AuditLog {\n  id         String  @id @default(cuid())\n  action     String // e.g. \"news.publish\", \"user.create\"\n  entityType String?\n  entityId   String?\n  before     Json?\n  after      Json?\n  ipAddress  String?\n\n  userId String?\n  user   User?   @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n  @@index([action])\n  @@index([createdAt])\n}\n",
